INSERT INTO feature VALUES('phase-distinction','modules','The static/dynamic phase distinction','signature-models','implemented','uncommon','mainstream languages','A module signature''s type members sit at the static stage of the two-point order static < dynamic, and a type that depends on a value member is refused by name as a phase dependence — the member and the dynamic member it reached — so a functor is applicative exactly when its static part is a function of its argument''s static part.','surface-lowering','corpus/model/modules/phase.gandr corpus/pathological/modules/phase.gandr','corpus/model/modules/phase.gandr',NULL);
